import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"xray.log","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/lua/reference/module-log.md","filePath":"ru/development/lua/reference/module-log.md","lastUpdated":1791683719000}`),a={name:`ru/development/lua/reference/module-log.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="xray-log" tabindex="-1">xray.log <a class="header-anchor" href="#xray-log" aria-label="Permalink to “xray.log”">​</a></h1><p>Записывает сообщения в систему журналирования Xray.</p><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.log&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="указатель-api" tabindex="-1">Указатель API <a class="header-anchor" href="#указатель-api" aria-label="Permalink to “Указатель API”">​</a></h2><table tabindex="0"><thead><tr><th>Категория</th><th>Член API</th><th>Описание</th></tr></thead><tbody><tr><td>Функция</td><td><a href="#log-debug"><code>log.Debug(...)</code></a></td><td>Запись сообщения debug</td></tr><tr><td>Функция</td><td><a href="#log-info"><code>log.Info(...)</code></a></td><td>Запись сообщения info</td></tr><tr><td>Функция</td><td><a href="#log-warning"><code>log.Warning(...)</code></a></td><td>Запись сообщения warning</td></tr><tr><td>Функция</td><td><a href="#log-error"><code>log.Error(...)</code></a></td><td>Запись сообщения error</td></tr></tbody></table><h2 id="функции" tabindex="-1">Функции <a class="header-anchor" href="#функции" aria-label="Permalink to “Функции”">​</a></h2><h3 id="log-debug" tabindex="-1">log.Debug <a class="header-anchor" href="#log-debug" aria-label="Permalink to “log.Debug”">​</a></h3><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">.</span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">Debug</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">...</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Записывает сообщение уровня <code>debug</code>.</p><p><strong>Параметры</strong></p><table tabindex="0"><thead><tr><th>Параметр</th><th>Тип</th><th>Описание / Требования</th></tr></thead><tbody><tr><td><code>...</code></td><td>Любое значение Lua</td><td>Необязательны; любое число значений, объединяемых по порядку</td></tr></tbody></table><p><strong>Возвращаемые значения</strong></p><p>Нет возвращаемых значений.</p><p><strong>Преобразование аргументов</strong></p><p>Допускается вызов без аргументов, а также <code>nil</code>, <code>&quot;&quot;</code>, <code>{}</code> и пустые срезы. Аргументы преобразуются в текст и объединяются по порядку без автоматической вставки пробелов или разделителей.</p><ul><li>Значения <a href="./data-types.html#error"><code>error</code></a> в первую очередь преобразуются в сообщения об ошибках.</li><li>Для остальных значений с функцией <code>__tostring</code> используется это преобразование; исключения из него передаются вызывающему коду.</li><li>Остальные значения используют строковое представление по умолчанию. <code>nil</code> становится <code>&quot;nil&quot;</code>, пустая строка не добавляет текст; таблицы и срезы не разворачиваются в списки элементов.</li></ul><p><strong>Условия вывода</strong></p><p>Сообщения имеют префикс с именем файла вызывающего скрипта. Вывод зависит от <a href="./../../../config/log.html#logobject"><code>log.loglevel</code></a>. Например, при уровне <code>warning</code> функции <code>Debug</code> и <code>Info</code> ничего не выводят и не вызывают преобразование аргументов через <code>__tostring</code>.</p><p>Ни одна из четырёх функций не возвращает <code>err</code>. Если присвоить результат вызова переменной, она получит <code>nil</code>; по этому значению нельзя определить, было ли сообщение успешно записано.</p><p><strong>Пример</strong></p><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">.</span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">Info</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;Запрашиваемый домен: &quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">, </span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">domain</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">.</span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">Warning</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;Ошибка запроса к вышестоящему серверу: &quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">, </span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">err</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="log-info" tabindex="-1">log.Info <a class="header-anchor" href="#log-info" aria-label="Permalink to “log.Info”">​</a></h3><p>Как описано выше.</p><h3 id="log-warning" tabindex="-1">log.Warning <a class="header-anchor" href="#log-warning" aria-label="Permalink to “log.Warning”">​</a></h3><p>Как описано выше.</p><h3 id="log-error" tabindex="-1">log.Error <a class="header-anchor" href="#log-error" aria-label="Permalink to “log.Error”">​</a></h3><p>Как описано выше.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};